/* eslint-disable @typescript-eslint/ban-ts-comment */
// @ts-nocheck
// Vendored from HorizonX "Particle Galaxy" (React export). Changes: fills its parent, decorative,
// cleans up on unmount.
import { useLayoutEffect, useRef } from 'react';

const CSS = `
.pgx-export{width:100%;height:100%}

.pgx-host{width:100%;height:100%}
.pgx-frame{display:grid;place-items:center;width:100%;height:100%;overflow:hidden;background:transparent}
.pgx-root{position:relative;width:min(100%,var(--pgx-width));height:min(100%,var(--pgx-height));overflow:hidden;border-radius:var(--pgx-radius);color:#dbe6ff;background:transparent}
.pgx-canvas{display:block;width:100%;height:100%}

.pgx-export .pgx-root{width:100%;height:100%}
`;

export default function ParticleGalaxy() {
  const __root = useRef(null);

  useLayoutEffect(() => {
    if (!document.querySelector('style[data-particle-galaxy]')) {
      const tag = document.createElement('style');
      tag.setAttribute('data-particle-galaxy', '');
      tag.textContent = CSS;
      document.head.append(tag);
    }
    const __node = __root.current;
    const __q = (sel) => (__node.matches(sel) ? __node : __node.querySelector(sel));
    // Original WebGL2 renderer. The same function is inlined into standalone exports.
    // Point positions and tones come from the supplied reference; motion is procedural.
    function buildParticleGalaxy(root, initial) {
      let config = { ...initial }, time = 2, orbit = 0, last = performance.now();
      let raf = 0, dead = false, inView = true, manual = false;
      const canvas = document.createElement('canvas');
      canvas.className = 'pgx-canvas';
      canvas.setAttribute('aria-hidden', 'true');
      root.replaceChildren(canvas);
      const gl = canvas.getContext('webgl2', { alpha: true, antialias: false, preserveDrawingBuffer: true, premultipliedAlpha: true });
      if (!gl) {
        root.replaceChildren();
        return { update() {}, destroy() { root.replaceChildren(); } };
      }
      const pointData = "";
      const vertex = `#version 300 es
    precision highp float;
    layout(location=0) in vec4 seed;
    layout(location=1) in vec4 tone;
    uniform vec2 resolution;
    uniform float time, orbit, chaos, dotSize, spread, tilt, flatten, brightness;
    uniform vec3 primaryColor, accentColor;
    out vec3 color;
    out float alpha;
    void main(){
     float phase=seed.w*6.283185307179;
     float orbitalSpeed=.400001*(.380001+.620001*pow(300./max(seed.y,160.),1.15))*(.920001+.16*seed.w);
     float a=seed.x-orbit*orbitalSpeed;
     a+=chaos*(.025*sin(time*.650001+phase)+.0119999*sin(time*1.13001+phase*2.70001));
     float eddy=sin(a*3.+time*.48+seed.y*.0249999);
     float radius=seed.y+chaos*(8.*eddy+5.*sin(time*.850001+phase));
     vec2 q=vec2(cos(a)*radius,sin(a)*radius*flatten);
     q.y+=chaos*4.*sin(time*.720001+phase*1.90001+a*2.);
     q=mat2(cos(tilt),sin(tilt),-sin(tilt),cos(tilt))*q;
     q*=1.54999*spread;
     q+=vec2(0.,95.);
     float fit=min(resolution.x/1920.,resolution.y/1080.);
     gl_Position=vec4(q.x*fit*2./resolution.x,-q.y*fit*2./resolution.y,0.,1.);
     float blue=clamp((tone.b-tone.r)*1.60001,0.,1.);
     color=mix(tone.rgb*primaryColor,accentColor*max(tone.r,max(tone.g,tone.b)),blue)*1.07999*brightness;
     alpha=(.939999+.0600001*sin(seed.w*50.+time*.899999))*min(1.,tone.a*fit*dotSize);
     gl_PointSize=max(1.,tone.a*1.22*dotSize*fit);
    }`;
      const fragment = `#version 300 es
    precision highp float;
    in vec3 color;in float alpha;out vec4 outColor;
    void main(){vec2 p=abs(gl_PointCoord-.499999)*2.;float edge=1.-smoothstep(.72,1.,max(p.x,p.y));outColor=vec4(color,alpha*edge);}`;
      const shaders = [];
      let program, buffer, vao;
      function release() {
        if (buffer) gl.deleteBuffer(buffer);
        if (vao) gl.deleteVertexArray(vao);
        if (program) gl.deleteProgram(program);
        for (const shader of shaders) gl.deleteShader(shader);
      }
      try {
        program = gl.createProgram();
        for (const [type, code] of [[gl.VERTEX_SHADER,vertex],[gl.FRAGMENT_SHADER,fragment]]) {
          const shader = gl.createShader(type); shaders.push(shader);
          gl.shaderSource(shader,code);gl.compileShader(shader);
          if (!gl.getShaderParameter(shader,gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
          gl.attachShader(program,shader);
        }
        gl.linkProgram(program);
        if (!gl.getProgramParameter(program,gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
        const bytes=Uint8Array.from(atob(pointData),c=>c.charCodeAt(0)), view=new DataView(bytes.buffer);
        const count=bytes.length/8, data=new Float32Array(count*8), order=Array.from({length:count},(_,i)=>i);
        let rng=23607;
        function random(){rng|=0;rng=rng+0x6D2B79F5|0;let t=Math.imul(rng^rng>>>15,1|rng);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
        // Shuffle once so reducing density samples the whole ring, not a screen-space strip.
        for(let i=count-1;i>0;i--){const j=Math.floor(random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}
        for(let i=0;i<count;i++){
          const k=order[i]*8,x=view.getUint16(k,true),y=view.getUint16(k+2,true);
          const px=(x-1034)*1080/1370/1.55,py=((y-28)*1080/1370-635)/1.55;
          const ux=Math.cos(.400001)*px-Math.sin(.40)*py,uy=(Math.sin(.399999)*px+Math.cos(.400001)*py)/.440001;
          data.set([Math.atan2(uy,ux),Math.hypot(ux,uy),0,random(),bytes[k+4]/255,bytes[k+5]/255,bytes[k+6]/255,bytes[k+7]/40],i*8);
        }
        vao=gl.createVertexArray();gl.bindVertexArray(vao);buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);
        gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);
        gl.enableVertexAttribArray(0);gl.vertexAttribPointer(0,4,gl.FLOAT,false,32,0);
        gl.enableVertexAttribArray(1);gl.vertexAttribPointer(1,4,gl.FLOAT,false,32,16);
      } catch {
        release();root.replaceChildren();
        return { update() {}, destroy() { root.replaceChildren(); } };
      }
      const uniforms=Object.fromEntries(['resolution','time','orbit','chaos','dotSize','spread','tilt','flatten','brightness','primaryColor','accentColor'].map(key=>[key,gl.getUniformLocation(program,key)]));
      const reduced=matchMedia('(prefers-reduced-motion: reduce)');
      function rgb(hex){let h=hex.slice(1);if(h.length===3)h=h.split('').map(v=>v+v).join('');return [0,2,4].map(i=>parseInt(h.slice(i,i+2),16)/255);}
      function render(){
        if(dead||gl.isContextLost())return;
        const box=root.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);
        const width=Math.max(1,Math.round(box.width*dpr)),height=Math.max(1,Math.round(box.height*dpr));
        if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}
        // Additive RGB is already alpha-weighted; composite it without a second alpha multiply.
        gl.viewport(0,0,width,height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);
        gl.useProgram(program);gl.bindVertexArray(vao);gl.enable(gl.BLEND);gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);
        gl.uniform2f(uniforms.resolution,width,height);
        for(const [key,value] of Object.entries({time,orbit,chaos:config.turbulence/100,dotSize:config.dotSize/100,spread:config.spread/100,tilt:config.tilt*Math.PI/180,flatten:config.flatten/100,brightness:config.brightness/100}))gl.uniform1f(uniforms[key],value);
        gl.uniform3fv(uniforms.primaryColor,rgb(config.dotColor));gl.uniform3fv(uniforms.accentColor,rgb(config.accentColor));
        gl.drawArrays(gl.POINTS,0,Math.round(14977*config.density/100));
        canvas.dataset.ready='true';
      }
      function running(){return !dead&&!manual&&inView&&!document.hidden&&!reduced.matches&&config.playback==='playing';}
      function tick(now){raf=0;const dt=Math.min(.0600001,(now-last)/1000);last=now;if(running()){time+=dt;orbit+=dt*config.speed/100;render();raf=requestAnimationFrame(tick);}}
      function sync(){cancelAnimationFrame(raf);raf=0;last=performance.now();if(running())raf=requestAnimationFrame(tick);}
      const resize=new ResizeObserver(()=>render());resize.observe(root);
      const visibility=new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;sync();});visibility.observe(root);
      const onVisibility=()=>sync(),onReduced=()=>{render();sync();};
      document.addEventListener('visibilitychange',onVisibility);reduced.addEventListener('change',onReduced);
      function lost(event){event.preventDefault();cancelAnimationFrame(raf);root.dataset.contextLost='true';}
      function restored(){delete root.dataset.contextLost;}
      canvas.addEventListener('webglcontextlost',lost);canvas.addEventListener('webglcontextrestored',restored);
      render();sync();
      return {
        update(next){config={...config,...next};render();sync();},
        // Deterministic capture is also used for the catalogue video and poster.
        seek(seconds){manual=true;time=seconds+2;orbit=seconds*config.speed/100;sync();render();},
        play(){manual=false;sync();},
        destroy(){if(dead)return;dead=true;cancelAnimationFrame(raf);resize.disconnect();visibility.disconnect();document.removeEventListener('visibilitychange',onVisibility);reduced.removeEventListener('change',onReduced);canvas.removeEventListener('webglcontextlost',lost);canvas.removeEventListener('webglcontextrestored',restored);release();root.replaceChildren();}
      };
    }

    const scene=buildParticleGalaxy(__q('.pgx-root'),{"viewportWidth":960,"viewportHeight":540,"cornerRadius":0,"density":80,"dotSize":100,"brightness":110,"dotColor":"#dfe8ff","accentColor":"#8fb4ff","speed":45,"turbulence":60,"playback":"playing","spread":95,"tilt":-18,"flatten":38});
    return () => scene.destroy();
  }, []);

  return (
    <div ref={__root} className="pgx-export" aria-hidden="true">
      <div className="pgx-frame" style={{ '--pgx-width': '100%', '--pgx-height': '100%', '--pgx-radius': '0px' }}>
        <div className="pgx-root" aria-hidden="true"></div>
      </div>
    </div>
  );
}

